"use client";

import * as React from "react";
import Link from "next/link";
import { Menu, Clock, User } from "lucide-react";
import { ThemeToggle } from "./theme-toggle";
import { MobileNav } from "./mobile-nav";

interface AuthUser {
  id: string;
  name: string;
  email: string;
}

export function Navbar() {
  const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);
  const [user, setUser] = React.useState<AuthUser | null>(null);

  // Check auth state deferred until idle to avoid main-thread blocking during initial paint
  React.useEffect(() => {
    let cancel = false;
    const fetchAuth = () => {
      if (cancel) return;
      fetch("/api/auth/me")
        .then((res) => res.json())
        .then((data) => {
          if (!cancel && data?.user) setUser(data.user);
        })
        .catch(() => {});
    };

    const handle =
      typeof window !== "undefined" && "requestIdleCallback" in window
        ? (window as unknown as { requestIdleCallback: (cb: () => void, opts?: { timeout: number }) => number }).requestIdleCallback(fetchAuth, { timeout: 1500 })
        : setTimeout(fetchAuth, 300);

    return () => {
      cancel = true;
      if (typeof window !== "undefined" && "cancelIdleCallback" in window && typeof handle === "number") {
        (window as unknown as { cancelIdleCallback: (id: number) => void }).cancelIdleCallback(handle);
      } else {
        clearTimeout(handle);
      }
    };
  }, []);

  return (
    <>
      {/* Liquid Glass Navigation SVG Filter */}
      <svg
        width="0"
        height="0"
        style={{
          position: "fixed",
          top: "0px",
          left: "0px",
          pointerEvents: "none",
          zIndex: 9998,
        }}
        aria-hidden="true"
      >
        <defs>
          <filter
            id="liquid-glass-l0ujt9j3o_filter"
            filterUnits="userSpaceOnUse"
            colorInterpolationFilters="sRGB"
            x="0"
            y="0"
            width="1000"
            height="89"
          >
            <feImage
              id="liquid-glass-l0ujt9j3o_map"
              width="1000"
              height="89"
              xlinkHref="data:image/png;base64,"
            />
            <feDisplacementMap
              in="SourceGraphic"
              in2="liquid-glass-l0ujt9j3o_map"
              xChannelSelector="R"
              yChannelSelector="G"
              scale={162.33410319333424}
            />
          </filter>
        </defs>
      </svg>

      <header className="sticky top-0 z-50 w-full px-4 sm:px-6 lg:px-8 py-2.5 transition-all duration-300 pointer-events-none">
        <div className="max-w-7xl mx-auto pointer-events-auto flex justify-center">
          <div
            className="w-full max-w-[1000px] min-h-[64px] sm:min-h-[89px] h-[72px] sm:h-[89px] px-6 sm:px-8 flex items-center justify-between transition-all duration-300 text-zinc-900 dark:text-white bg-white/80 dark:bg-black/40 border border-black/10 dark:border-white/20 text-shadow-xs"
            style={{
              overflow: "hidden",
              borderRadius: "74.5px",
              boxShadow:
                "rgba(0, 0, 0, 0.25) 0px 4px 8px, rgba(0, 0, 0, 0.15) 0px -10px 25px inset, rgba(255, 255, 255, 0.74) 0px -1px 4px 1px inset",
              backdropFilter:
                'url("#liquid-glass-l0ujt9j3o_filter") blur(2px) brightness(0.475) saturate(2)',
              WebkitBackdropFilter:
                'url("#liquid-glass-l0ujt9j3o_filter") blur(2px) brightness(0.475) saturate(2)',
              pointerEvents: "auto",
            }}
          >
            <div className="flex items-center">
              <Link
                href="/"
                className="flex items-center gap-2.5 group focus:outline-none transition-transform duration-200 active:scale-95"
              >
                <div className="flex items-center gap-2 font-mono">
                  <span
                    className="flex items-center justify-center w-4 h-4 bg-black/10 text-zinc-900 border border-black/20 dark:bg-white/20 dark:text-white dark:border-white/40 text-[10px] font-bold select-none transition-transform duration-200 group-hover:rotate-12"
                    style={{ borderRadius: "2px" }}
                  >
                    /
                  </span>
                  <span className="font-mono text-sm font-bold tracking-tight text-zinc-950 dark:text-white uppercase drop-shadow-xs">
                    PDF STUDIO
                  </span>
                </div>
              </Link>
            </div>

            {/* Right Controls */}
            <div className="flex items-center gap-2 sm:gap-3">
              {user && (
                <Link
                  href="/history"
                  className="hidden sm:inline-flex items-center gap-1.5 px-2.5 py-1 text-xs font-mono font-medium text-zinc-800 hover:text-black hover:bg-black/10 dark:text-white/90 dark:hover:text-white dark:hover:bg-white/15 transition-all duration-150 rounded"
                >
                  <Clock className="w-3.5 h-3.5 text-zinc-800 dark:text-white/90" />
                  <span>HISTORY</span>
                </Link>
              )}

              <ThemeToggle className="text-zinc-800 hover:text-black hover:bg-black/10 dark:text-white/90 dark:hover:text-white dark:hover:bg-white/15 transition-colors w-9 h-9" />

              {user ? (
                <Link
                  href="/account"
                  prefetch={false}
                  className="inline-flex items-center justify-center px-3 py-1 font-mono text-xs font-bold text-zinc-900 hover:bg-black/10 border border-black/20 dark:text-white dark:hover:bg-white/15 dark:border-white/25 btn-interactive transition-colors"
                  style={{ borderRadius: "6px" }}
                >
                  <User className="w-3 h-3 mr-1 text-zinc-900 dark:text-white" />
                  <span>{user.name.split(" ")[0]}</span>
                </Link>
              ) : (
                <>
                  <Link
                    href="/login"
                    prefetch={false}
                    className="inline-flex items-center justify-center px-3.5 py-1 font-mono text-xs font-bold text-white bg-zinc-900 hover:bg-black border border-zinc-900 dark:text-white dark:bg-white/20 dark:hover:bg-white/30 dark:border-white/40 btn-interactive shadow-xs transition-colors"
                    style={{ borderRadius: "6px" }}
                  >
                    sign in
                  </Link>
                  <Link
                    href="/register"
                    prefetch={false}
                    className="inline-flex items-center justify-center px-3 py-1 font-mono text-xs font-bold text-zinc-800 hover:text-black hover:bg-black/10 border border-black/20 dark:text-white/90 dark:hover:text-white dark:hover:bg-white/15 dark:border-white/25 btn-interactive transition-colors"
                    style={{ borderRadius: "6px" }}
                  >
                    register
                  </Link>
                </>
              )}

              {/* Mobile Drawer Trigger */}
              <button
                type="button"
                onClick={() => setMobileMenuOpen(true)}
                className="lg:hidden p-1.5 rounded text-zinc-800 hover:text-black hover:bg-black/10 dark:text-white/90 dark:hover:text-white dark:hover:bg-white/15 transition-colors cursor-pointer"
                aria-label="Open mobile menu"
              >
                <Menu className="w-4 h-4 text-zinc-900 dark:text-white" />
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Mobile Drawer */}
      <MobileNav
        isOpen={mobileMenuOpen}
        onClose={() => setMobileMenuOpen(false)}
      />
    </>
  );
}
